# ==========================================
# 🗄️ MONGODB STORAGE STATS HELPER
# ==========================================
def get_mongo_storage_stats() -> dict:
    """
    Get MongoDB storage usage. Works on Atlas M0 (free 512MB) and paid tiers.
    Returns a dict with all fields needed to display a storage bar + alert.
    """
    try:
        stats      = db.command("dbStats")
        data_mb    = stats.get("dataSize",    0) / 1_048_576
        storage_mb = stats.get("storageSize", 0) / 1_048_576
        index_mb   = stats.get("indexSize",   0) / 1_048_576
        total_mb   = stats.get("totalSize",   0) / 1_048_576
        fs_total   = stats.get("fsTotalSize", 0) / 1_048_576
        fs_used    = stats.get("fsUsedSize",  0) / 1_048_576

        if fs_total > 0:
            # Dedicated/paid tier — use real filesystem values
            used_mb   = fs_used
            cap_mb    = fs_total
            cap_label = f"{cap_mb:.0f}MB filesystem"
        else:
            # Atlas M0 free tier — totalSize is always 0 on M0.
            # Use dataSize + indexSize which Atlas DOES populate correctly.
            used_mb   = data_mb + index_mb
            cap_mb    = 512.0
            cap_label = "512MB Atlas M0 free tier"

        pct    = min(used_mb / cap_mb * 100, 100) if cap_mb > 0 else 0.0
        filled = round(pct / 5)
        empty  = 20 - filled
        bar    = "█" * filled + "░" * empty

        if pct >= 90:
            risk_icon  = "🔴"
            risk_label = "CRITICAL — upgrade NOW"
        elif pct >= 75:
            risk_icon  = "🟠"
            risk_label = "HIGH — plan upgrade soon"
        elif pct >= 60:
            risk_icon  = "🟡"
            risk_label = "MODERATE — monitor"
        else:
            risk_icon  = "🟢"
            risk_label = "HEALTHY"

        return {
            "ok":        True,
            "used_mb":   used_mb,
            "cap_mb":    cap_mb,
            "pct":       pct,
            "bar":       bar,
            "risk_icon": risk_icon,
            "risk_label": risk_label,
            "cap_label": cap_label,
            "data_mb":   data_mb,
            "index_mb":  index_mb,
            "storage_mb": storage_mb,
        }
    except Exception as e:
        return {"ok": False, "error": str(e)[:100]}


def log_action(action_type, user_id, details="", bot="bot2", user_name="", channel=""):
    """Log actions to console, memory, AND MongoDB for live terminal display (works on Render)"""
    _now = now_local()
    timestamp = _now.strftime('%b %d  %I:%M:%S %p')  # e.g. Apr 27  01:23:45 PM

    # Color codes for console terminal
    CYAN = '\033[96m'
    GREEN = '\033[92m'
    RESET = '\033[0m'
    BOLD = '\033[1m'

    # Console output with colors — include user info if available
    user_tag = f" [{user_name} | {user_id}]" if user_name else (f" [ID:{user_id}]" if user_id else "")
    print(f"{CYAN}[{timestamp}]{user_tag}{RESET} {BOLD}{action_type}{RESET}")
    if details:
        print(f"  📋 {details}")
    print(f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")

    # Build log entry
    log_entry = {
        "timestamp": timestamp,
        "created_at": now_local(),
        "bot": bot,
        "action": action_type,
        "user_id": user_id,
        "user_name": user_name,
        "channel": channel,
        "details": details,
        "full_text": f"[{timestamp}]{user_tag} {action_type}" + (f" &gt; {details}" if details else "")
    }

    # Add to in-memory list
    if bot == "bot1":
        bot1_logs.append(log_entry)
        if len(bot1_logs) > MAX_LOGS:
            bot1_logs.pop(0)
    else:
        bot2_logs.append(log_entry)
        if len(bot2_logs) > MAX_LOGS:
            bot2_logs.pop(0)
 
    # Persist to MongoDB (for Render cross-process live view)
    try:
        col_live_logs.insert_one(log_entry)
        # Keep collection trimmed — delete oldest beyond MAX_LOGS*2 per bot
        count = col_live_logs.count_documents({"bot": bot})
        if count > MAX_LOGS * 2:
            oldest = list(col_live_logs.find({"bot": bot}, {"_id": 1}).sort("created_at", 1).limit(count - MAX_LOGS))
            if oldest:
                col_live_logs.delete_many({"_id": {"$in": [d["_id"] for d in oldest]}})
    except Exception:
        pass  # Never let logging break the bot

def get_terminal_logs(bot="bot2", limit=50):
    """Get raw terminal logs — reads from MongoDB first (Render-safe), falls back to memory.
    Shows 12-hour AM/PM with full date, user ID, name, and channel."""
    try:
        # Read from MongoDB for cross-process / Render support
        docs = list(col_live_logs.find({"bot": bot}, {"_id": 0}).sort("created_at", -1).limit(limit))
        if docs:
            docs.reverse()  # Oldest first (terminal style)
            log_lines = []
            MAX_CHARS = 3500
            current_length = 0
            for doc in docs:
                # Prefer reconstructing timestamp from created_at (datetime) for accuracy
                raw_ca = doc.get("created_at")
                if raw_ca and hasattr(raw_ca, "strftime"):
                    ts = raw_ca.strftime('%b %d  %I:%M:%S %p')
                else:
                    ts = doc.get("timestamp", "??:??:?? ?M")

                action  = doc.get("action", "")
                detail  = doc.get("details", "")
                uid     = doc.get("user_id", "")
                uname   = doc.get("user_name", "")
                chan    = doc.get("channel", "")

                # Build user tag: name + ID + optional channel
                parts = []
                if uname:
                    parts.append(str(uname))
                if uid:
                    parts.append(f"ID:{uid}")
                if chan:
                    parts.append(f"ch:{chan}")
                user_tag = (" [" + " | ".join(parts) + "]") if parts else ""

                line = f"[{ts}]{user_tag} {_html_escape(action)}" + (f" &gt; {_html_escape(str(detail))}" if detail else "")
                if current_length + len(line) + 1 > MAX_CHARS:
                    break
                log_lines.append(line)
                current_length += len(line) + 1
            return "\n".join(log_lines) if log_lines else ">> NO LOGS YET..."
    except Exception:
        pass

    # Fallback to in-memory
    logs = bot1_logs if bot == "bot1" else bot2_logs
    if not logs:
        return ">> SYSTEM INITIALIZED. WAITING FOR EVENTS..."
    recent_logs = logs[-limit:]
    MAX_CHARS = 3500
    final_lines = []
    current_length = 0
    for log in reversed(recent_logs):
        uid     = log.get("user_id", "")
        uname   = log.get("user_name", "")
        if uname and uid:
            user_tag = f" [{uname} | {uid}]"
        elif uid:
            user_tag = f" [ID:{uid}]"
        else:
            user_tag = ""
        line = f"[{log['timestamp']}]{user_tag} {_html_escape(log['action'])} &gt; {_html_escape(log.get('details', ''))}"
        if current_length + len(line) + 1 > MAX_CHARS:
            break
        final_lines.insert(0, line)
        current_length += len(line) + 1
    return "\n".join(final_lines)

