@dp.message(F.text == "🩺 BOT 1 DIAGNOSIS")
async def bot1_diagnosis(message: types.Message):
    """Run comprehensive diagnosis on Bot 1 system"""
    if not await has_permission(message.from_user.id, "diagnosis"):
        await message.answer("⛔ You don't have permission to use DIAGNOSIS.", parse_mode="HTML")
        return
    log_action("DIAGNOSIS", message.from_user.id, "Running Bot 1 Diagnosis", "bot1")
    
    status_msg = await message.answer(
        "🔄 <b>INITIALIZING BOT 1 DIAGNOSTICS</b>\n\n"
        "⏳ Scanning system components...\n"
        "📊 Analyzing database health...\n"
        "🔍 Checking data integrity...",
        parse_mode="HTML"
    )
    
    await asyncio.sleep(1.2)
    
    # Initialize tracking
    issues = []
    warnings = []
    info_items = []
    total_checks = 0
    checks_passed = 0
    
    # ═══════════════════════════════════════
    # PHASE 1: DATABASE CONNECTION & LATENCY
    # ═══════════════════════════════════════
    total_checks += 1
    db_status = "Unknown"
    db_latency = 0
    
    try:
        start = time.time()
        client.admin.command('ping')
        db_latency = (time.time() - start) * 1000
        
        if db_latency < 50:
            db_status = f"✅ Excellent ({db_latency:.1f}ms)"
            checks_passed += 1
        elif db_latency < 150:
            db_status = f"⚠️ Acceptable ({db_latency:.1f}ms)"
            warnings.append(f"Database latency is elevated: {db_latency:.1f}ms (normal <50ms)")
        else:
            db_status = f"❌ Slow ({db_latency:.1f}ms)"
            issues.append(f"<b>Database Performance Critical:</b> Latency {db_latency:.1f}ms exceeds safe threshold.")
            
    except Exception as e:
        db_status = "❌ Connection Failed"
        issues.append(f"<b>Database Connection Error:</b> {str(e)[:100]}")
    
    # ═══════════════════════════════════════
    # PHASE 2: COLLECTION VERIFICATION
    # ═══════════════════════════════════════
    total_checks += 1
    collections_ok = True
    
    try:
        expected_collections = [
            "bot1_msa_ids", "bot1_user_verification", "bot1_support_tickets",
            "bot1_banned_users", "bot1_suspended_features"
        ]
        existing = db.list_collection_names()
        missing = [c for c in expected_collections if c not in existing]
        
        if missing:
            warnings.append(f"<b>Missing Collections:</b> {', '.join(missing)}")
            collections_ok = False
        else:
            checks_passed += 1
            info_items.append(f"All {len(expected_collections)} core collections present")
            
    except Exception as e:
        issues.append(f"<b>Collection Check Failed:</b> {str(e)[:80]}")
        collections_ok = False
    
    # ═══════════════════════════════════════
    # PHASE 3: USER DATA HEALTH
    # ═══════════════════════════════════════
    total_checks += 1
    
    try:
        # Exclude retired MSA IDs so health check reflects real active users
        total_users = col_msa_ids.count_documents({"retired": {"$ne": True}})
        pending_vers = col_user_verification.count_documents({"verification_pending": True})
        banned_users = col_banned_users.count_documents({})
        suspended_users = col_suspended_features.count_documents({})
        
        if total_users == 0:
            warnings.append("<b>No Users Found:</b> Database appears to be empty or not initialized.")
        else:
            checks_passed += 1
            info_items.append(f"{total_users:,} registered users")
            
            # Real verification queue check (only count users with active pending verification requests)
            if pending_vers > 50:
                issues.append(f"<b>Verification Backlog:</b> {pending_vers} pending verification requests in queue.")
            elif pending_vers > 20:
                warnings.append(f"<b>Elevated Verification Queue:</b> {pending_vers} pending verifications.")
            
            # Ban rate analysis
            if total_users > 0:
                ban_rate = (banned_users / total_users) * 100
                if ban_rate > 30:
                    issues.append(f"<b>Extreme Ban Rate:</b> {ban_rate:.1f}% ({banned_users}/{total_users}) - Possible attack or misconfiguration")
                elif ban_rate > 15:
                    warnings.append(f"<b>High Ban Rate:</b> {ban_rate:.1f}% ({banned_users}/{total_users})")
                else:
                    info_items.append(f"Ban rate: {ban_rate:.1f}%")
                    
    except Exception as e:
        issues.append(f"<b>User Data Check Failed:</b> {str(e)[:80]}")
    
    # ═══════════════════════════════════════
    # PHASE 4: SUPPORT SYSTEM HEALTH
    # ═══════════════════════════════════════
    total_checks += 1
    
    try:
        open_tickets = col_support_tickets.count_documents({"status": "open"})
        total_tickets = col_support_tickets.count_documents({})
        
        if open_tickets > 20:
            issues.append(f"<b>Support Overload:</b> {open_tickets} open tickets! Urgent admin attention required.")
        elif open_tickets > 10:
            warnings.append(f"<b>Support Backlog:</b> {open_tickets} open tickets pending review.")
        elif open_tickets > 5:
            info_items.append(f"{open_tickets} open support tickets (manageable)")
        else:
            checks_passed += 1
            info_items.append(f"Support queue healthy ({open_tickets} open)")
            
    except Exception as e:
        warnings.append(f"Support check error: {str(e)[:60]}")
    
    # ═══════════════════════════════════════
    # PHASE 6: LOG ERROR ANALYSIS
    # ═══════════════════════════════════════
    total_checks += 1
    
    try:
        error_keywords = ['error', 'failed', 'exception', 'crash']
        error_logs = [
            l for l in bot1_logs 
            if any(kw in l.get('details', '').lower() for kw in error_keywords)
        ]
        
        if error_logs:
            if len(error_logs) > 5:
                issues.append(f"<b>High Error Rate:</b> {len(error_logs)} errors detected in recent logs.")
            else:
                warnings.append(f"<b>Recent Errors:</b> {len(error_logs)} error events logged.")
        else:
            checks_passed += 1
            info_items.append("No errors detected in recent logs")
            
    except Exception as e:
        info_items.append("Log analysis skipped")

    # ═══════════════════════════════════════
    # PHASE 7: DATABASE STORAGE SPACE
    # ═══════════════════════════════════════
    total_checks += 1
    db_space_line = ""
    db_bar_line   = ""

    try:
        stats      = db.command("dbStats")
        data_mb    = stats.get("dataSize",    0) / 1_048_576
        storage_mb = stats.get("storageSize", 0) / 1_048_576
        index_mb   = stats.get("indexSize",   0) / 1_048_576
        total_mb   = stats.get("totalSize",   0) / 1_048_576
        fs_total   = stats.get("fsTotalSize", 0) / 1_048_576
        fs_used    = stats.get("fsUsedSize",  0) / 1_048_576

        if fs_total > 0:
            pct    = min(fs_used / fs_total * 100, 100)
            filled = round(pct / 5)
            empty  = 20 - filled
            risk   = ("🔴 CRITICAL" if pct > 90 else
                      "🟠 HIGH"     if pct > 75 else
                      "🟡 MODERATE"  if pct > 50 else
                      "🟢 HEALTHY")
            bar    = "█" * filled + "░" * empty
            db_bar_line = (
                f"<b>Filesystem:</b> <code>[{bar}]</code> "
                f"{pct:.1f}% ({fs_used:.0f}MB / {fs_total:.0f}MB) — {risk}"
            )
            if pct > 90:
                issues.append(
                    f"<b>STORAGE CRITICAL:</b> {pct:.1f}% filesystem used "
                    f"({fs_used:.0f}/{fs_total:.0f}MB) — free space urgently needed"
                )
            elif pct > 80:
                warnings.append(f"Storage high: {pct:.1f}% used ({fs_used:.0f}/{fs_total:.0f}MB)")
            else:
                checks_passed += 1
        else:
            # Atlas M0: totalSize=0. Use dataSize+indexSize (both populated by Atlas).
            m0_used = data_mb + index_mb
            m0_cap  = 512.0
            pct     = min(m0_used / m0_cap * 100, 100)
            filled  = round(pct / 5)
            empty   = 20 - filled
            risk    = ("🔴 CRITICAL" if pct > 90 else
                       "🟠 HIGH"     if pct > 75 else
                       "🟡 MODERATE" if pct > 50 else
                       "🟢 HEALTHY")
            bar     = "█" * filled + "░" * empty
            db_bar_line = (
                f"<b>DB Used:</b> <code>[{bar}]</code> "
                f"{pct:.1f}% of 512MB M0 cap ({m0_used:.1f}MB used) — {risk}"
            )
            checks_passed += 1

        db_space_line = (
            f"📦 Data: <code>{data_mb:.1f}MB</code>  "
            f"💾 Storage: <code>{storage_mb:.1f}MB</code>  "
            f"🔖 Indexes: <code>{index_mb:.1f}MB</code>"
        )
        info_items.append(f"DB space — data:{data_mb:.1f}MB storage:{storage_mb:.1f}MB idx:{index_mb:.1f}MB")
    except Exception as space_err:
        db_space_line = ""
        db_bar_line   = ""
        info_items.append(f"DB space check skipped: {str(space_err)[:50]}")

    # ═══════════════════════════════════════
    # GENERATE COMPREHENSIVE REPORT
    # ═══════════════════════════════════════
    
    scan_time = now_local().strftime('%Y-%m-%d %H:%M:%S')
    health_percentage = int((checks_passed / total_checks) * 100) if total_checks > 0 else 0
    
    # Determine overall status
    if health_percentage >= 90:
        status_icon = "✅"
        status_text = "EXCELLENT"
    elif health_percentage >= 70:
        status_icon = "⚠️"
        status_text = "GOOD"
    elif health_percentage >= 50:
        status_icon = "⚠️"
        status_text = "DEGRADED"
    else:
        status_icon = "❌"
        status_text = "CRITICAL"
    
    report = f"📱 <b>BOT 1 DIAGNOSTIC REPORT</b>\n"
    report += "━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
    report += f"🕐 <b>Scan Time:</b> {scan_time}\n"
    report += f"💾 <b>Database:</b> {db_status}\n"
    report += f"📊 <b>Health Score:</b> {checks_passed}/{total_checks} ({health_percentage}%)\n"
    report += f"🎯 <b>Status:</b> {status_icon} {status_text}\n"
    if db_space_line:
        report += f"🗄️ <b>Space:</b> {db_space_line}\n"
    if db_bar_line:
        report += f"📊 {db_bar_line}\n"
    report += "\n"
    
    # Critical issues section
    if issues:
        report += f"❌ <b>CRITICAL ISSUES ({len(issues)}):</b>\n"
        for i, issue in enumerate(issues, 1):
            report += f"{i}. {issue}\n"
        report += "\n"
    
    # Warnings section
    if warnings:
        report += f"⚠️ <b>WARNINGS ({len(warnings)}):</b>\n"
        for i, warning in enumerate(warnings, 1):
            report += f"{i}. {warning}\n"
        report += "\n"
    
    # System info
    if info_items:
        report += "ℹ️ <b>SYSTEM INFO:</b>\n"
        for info in info_items[:5]:  # Limit to prevent message overflow
            report += f"• {info}\n"
        report += "\n"
    
    # Solutions section
    solutions = []
    for issue in issues:
        il = issue.lower()
        if "database" in il or "latency" in il:
            solutions.append("🔧 DB slow: Check MongoDB Atlas cluster load, upgrade tier, or add indexes")
        if "verification queue" in il or "stuck in queue" in il:
            solutions.append("🔧 Verification queue: Restart Bot 1, check CHANNEL_ID is correct, verify bot has admin rights in vault")
        if "ban rate" in il:
            solutions.append("🔧 High ban rate: Review recent ban reasons in SHOOT panel, check if auto-ban threshold is too low")
        if "support overload" in il:
            solutions.append("🔧 Support backlog: Go to 💬 SUPPORT → resolve tickets, or increase response team")
        if "missing collections" in il:
            solutions.append("🔧 Missing collections will be auto-created on first write — restart Bot 1 to trigger initialization")
        if "high error rate" in il:
            solutions.append("🔧 Error logs: Check DIAGNOSIS → logs for specific error patterns, may need bot restart")
    for warn in warnings:
        wl = warn.lower()
        if "no users found" in wl:
            solutions.append("💡 No users yet — share start links (IG/YT/IGCC/YTCODE) or wait for vault joins")
        if "latency" in wl:
            solutions.append("💡 DB latency elevated — likely temporary; retry in a few minutes")
        if "support backlog" in wl:
            solutions.append("💡 Review open tickets in 💬 SUPPORT section")

    # Final verdict
    if not issues and not warnings:
        report += "✅ <b>ALL SYSTEMS OPERATIONAL</b>\n"
        report += "No issues detected. Bot 1 is healthy."
    elif issues:
        report += "🚨 <b>ACTION REQUIRED</b>\n"
        report += "Critical issues detected. Address immediately."
    else:
        report += "✅ <b>SYSTEM FUNCTIONAL</b>\n"
        report += "Minor warnings — no immediate action needed."

    if solutions:
        report += "\n\n💡 <b>POSSIBLE SOLUTIONS:</b>\n"
        for s in solutions[:5]:
            report += f"• {s}\n"

    await status_msg.edit_text(report, parse_mode="HTML")

@dp.message(F.text == "🩺 BOT 2 DIAGNOSIS")
async def bot2_diagnosis(message: types.Message):
    """Run comprehensive diagnosis on Bot 2 admin system"""
    if not await has_permission(message.from_user.id, "diagnosis"):
        await message.answer("⛔ You don't have permission to use DIAGNOSIS.", parse_mode="HTML")
        return
    log_action("DIAGNOSIS", message.from_user.id, "Running Bot 2 Diagnosis", "bot2")

    status_msg = await message.answer(
        "🔄 <b>INITIALIZING BOT 2 DIAGNOSTICS</b>\n\n"
        "⏳ Scanning system components...\n"
        "📊 Analyzing admin database health...\n"
        "🔍 Checking configurations...",
        parse_mode="HTML"
    )

    await asyncio.sleep(1.2)
    
    # Initialize tracking
    issues = []
    warnings = []
    info_items = []
    total_checks = 0
    checks_passed = 0
    
    # ═══════════════════════════════════════
    # PHASE 1: SYSTEM FILES & CONFIGURATION
    # ═══════════════════════════════════════
    total_checks += 1
    
    try:
        # Check files that are actually expected in this deployment
        # bot2.py = the running script; credentials.json = Google Drive API key (optional)
        # .env is NOT checked — Render injects env vars directly, no file needed
        required_files = ["bot2.py"]
        optional_files = ["credentials.json"]

        missing_req = [f for f in required_files if not os.path.exists(f)]
        missing_opt = [f for f in optional_files if not os.path.exists(f)]

        if missing_req:
            issues.append(f"<b>Missing Core Files:</b> {', '.join(missing_req)}")
        else:
            checks_passed += 1
            info_items.append("Core bot file present (bot2.py)")

        if missing_opt:
            info_items.append(f"Optional not found: {', '.join(missing_opt)} (Drive backups may be unavailable)")

    except Exception as e:
        issues.append(f"<b>File System Check Failed:</b> {_html_escape(str(e)[:80])}")
    
    # ═══════════════════════════════════════
    # PHASE 2: BACKUP SYSTEM HEALTH
    # ═══════════════════════════════════════
    total_checks += 1
    
    try:
        backup_dir = "backups"
        if not os.path.exists(backup_dir):
            os.makedirs(backup_dir, exist_ok=True)
            
        backup_files = [
            f for f in os.listdir(backup_dir) 
            if f.endswith(('.zip', '.json', '.csv', '.txt', '.tar.gz', '.bak'))
        ]
        
        # Check MongoDB backup collections
        mongo_backups = list(db["bot2_backups"].find({}).sort("_id", -1).limit(10))
        mongo_history = list(db["bot2_backup_history"].find({}).sort("_id", -1).limit(10))
        
        last_backup_dt = None
        
        # 1. Check local backup files (including .zip)
        if backup_files:
            backup_files.sort(key=lambda x: os.path.getmtime(os.path.join(backup_dir, x)), reverse=True)
            newest_file = backup_files[0]
            newest_path = os.path.join(backup_dir, newest_file)
            last_backup_dt = datetime.fromtimestamp(os.path.getmtime(newest_path))
            
        # 2. Check MongoDB backup records
        for m_doc in mongo_backups + mongo_history:
            m_ts = m_doc.get("timestamp") or m_doc.get("created_at") or m_doc.get("backup_date")
            if isinstance(m_ts, datetime):
                if last_backup_dt is None or m_ts > last_backup_dt:
                    last_backup_dt = m_ts
            elif isinstance(m_ts, str):
                try:
                    parsed_dt = datetime.strptime(m_ts.split(".")[0], "%Y-%m-%d %H:%M:%S")
                    if last_backup_dt is None or parsed_dt > last_backup_dt:
                        last_backup_dt = parsed_dt
                except Exception:
                    pass

        if last_backup_dt is None:
            warnings.append("<b>No Backups Found:</b> No local or database backups detected. Run first backup now.")
        else:
            now = now_local()
            if last_backup_dt.tzinfo is not None and now.tzinfo is None:
                now = now.astimezone()
            elif last_backup_dt.tzinfo is None and now.tzinfo is not None:
                last_backup_dt = last_backup_dt.replace(tzinfo=now.tzinfo)

            backup_age = max(0, (now - last_backup_dt).days)
            total_count = len(backup_files) + len(mongo_backups)
            
            if backup_age > 7:
                warnings.append(f"<b>Backup Advisory:</b> Last backup was {backup_age} days ago. Tap BACKUP MENU to trigger fresh backup.")
                info_items.append(f"Latest backup: {backup_age}d ago ({total_count} backups available)")
            elif backup_age > 3:
                warnings.append(f"<b>Backup Advisory:</b> Last backup was {backup_age} days ago.")
                info_items.append(f"Latest backup: {backup_age}d ago ({total_count} backups available)")
            else:
                checks_passed += 1
                info_items.append(f"Latest backup: {backup_age}d ago ({total_count} backups available)")
                
    except Exception as e:
        warnings.append(f"Backup check error: {str(e)[:60]}")
    
    # ═══════════════════════════════════════
    # PHASE 3: LOG SYSTEM HEALTH
    # ═══════════════════════════════════════
    total_checks += 1
    
    try:
        bot1_log_count = len(bot1_logs)
        bot2_log_count = len(bot2_logs)
        
        log_health = True
        
        if bot2_log_count >= MAX_LOGS:
            warnings.append(f"<b>Log Buffer Full:</b> Bot 2 buffer at capacity ({MAX_LOGS}). Active rotation.")
            log_health = False
            
        if bot1_log_count >= MAX_LOGS:
            warnings.append(f"<b>Log Buffer Full:</b> Bot 1 tracking buffer at capacity.")
            log_health = False
        
        if log_health:
            checks_passed += 1
            info_items.append(f"Logs: Bot1={bot1_log_count}, Bot2={bot2_log_count}")
            
        # Check for error patterns
        error_count_bot2 = sum(1 for l in bot2_logs if 'error' in l.get('details', '').lower())
        if error_count_bot2 > 5:
            warnings.append(f"<b>Admin Errors Detected:</b> {error_count_bot2} error events in Bot 2 logs.")
            
    except Exception as e:
        warnings.append(f"Log system check skipped: {_html_escape(str(e)[:50])}")
    
    # ═══════════════════════════════════════
    # PHASE 4: DATABASE CONNECTION
    # ═══════════════════════════════════════
    total_checks += 1
    
    try:
        # Test MongoDB connection from admin side
        start = time.time()
        client.admin.command('ping')
        db_latency = (time.time() - start) * 1000
        
        if db_latency < 100:
            checks_passed += 1
            info_items.append(f"DB responsive ({db_latency:.1f}ms)")
        else:
            warnings.append(f"<b>DB Latency High:</b> {db_latency:.1f}ms (admin operations may be slow)")
            
    except Exception as e:
        issues.append(f"<b>DB Connection Error:</b> {_html_escape(str(e)[:80])}")
    
    # ═══════════════════════════════════════
    # PHASE 5: ENVIRONMENT & SECURITY
    # ═══════════════════════════════════════
    total_checks += 1
    
    try:
        # Check the actual required environment variables for Bot 2
        env_vars = ['BOT_2_TOKEN', 'BOT_1_TOKEN', 'MONGO_URI', 'MASTER_ADMIN_ID', 'BACKUP_MONGO_URI']
        missing_env = []

        for var in env_vars:
            if not os.getenv(var):
                missing_env.append(var)
        
        if missing_env:
            issues.append(f"<b>Missing Env Variables:</b> {', '.join(missing_env)}")
        else:
            checks_passed += 1
            info_items.append("All environment vars configured")
            
    except Exception as e:
        warnings.append(f"Environment check skipped: {_html_escape(str(e)[:50])}")
    
    # ═══════════════════════════════════════
    # PHASE 6: DRIVE API STATUS (if using)
    # ═══════════════════════════════════════
    total_checks += 1
    
    try:
        if os.path.exists('token.json'):
            with open('token.json', 'r') as f:
                token_data = json.load(f)
                if 'token' in token_data or 'access_token' in token_data:
                    checks_passed += 1
                    info_items.append("Drive API token valid")
                else:
                    warnings.append("<b>Drive Token Malformed:</b> Backup uploads may fail.")
        else:
            warnings.append("<b>No Drive Token:</b> Cloud backups unavailable.")
            
    except Exception as e:
        info_items.append("Drive check skipped")

    # ═══════════════════════════════════════
    # PHASE 7: DATABASE STORAGE SPACE
    # ═══════════════════════════════════════
    total_checks += 1
    db_space_line = ""
    db_bar_line   = ""

    try:
        stats      = db.command("dbStats")
        data_mb    = stats.get("dataSize",    0) / 1_048_576
        storage_mb = stats.get("storageSize", 0) / 1_048_576
        index_mb   = stats.get("indexSize",   0) / 1_048_576
        total_mb   = stats.get("totalSize",   0) / 1_048_576
        fs_total   = stats.get("fsTotalSize", 0) / 1_048_576
        fs_used    = stats.get("fsUsedSize",  0) / 1_048_576

        if fs_total > 0:
            pct    = min(fs_used / fs_total * 100, 100)
            filled = round(pct / 5)
            empty  = 20 - filled
            risk   = ("🔴 CRITICAL" if pct > 90 else
                      "🟠 HIGH"     if pct > 75 else
                      "🟡 MODERATE"  if pct > 50 else
                      "🟢 HEALTHY")
            bar    = "█" * filled + "░" * empty
            db_bar_line = (
                f"<b>Filesystem:</b> <code>[{bar}]</code> "
                f"{pct:.1f}% ({fs_used:.0f}MB / {fs_total:.0f}MB) — {risk}"
            )
            if pct > 90:
                issues.append(
                    f"<b>STORAGE CRITICAL:</b> {pct:.1f}% filesystem used "
                    f"({fs_used:.0f}/{fs_total:.0f}MB) — free space urgently needed"
                )
            elif pct > 80:
                warnings.append(f"Storage high: {pct:.1f}% used ({fs_used:.0f}/{fs_total:.0f}MB)")
            else:
                checks_passed += 1
        else:
            # Atlas M0: totalSize=0. Use dataSize+indexSize (both populated by Atlas).
            m0_used = data_mb + index_mb
            m0_cap  = 512.0
            pct     = min(m0_used / m0_cap * 100, 100)
            filled  = round(pct / 5)
            empty   = 20 - filled
            risk    = ("🔴 CRITICAL" if pct > 90 else
                       "🟠 HIGH"     if pct > 75 else
                       "🟡 MODERATE" if pct > 50 else
                       "🟢 HEALTHY")
            bar     = "█" * filled + "░" * empty
            db_bar_line = (
                f"<b>DB Used:</b> <code>[{bar}]</code> "
                f"{pct:.1f}% of 512MB M0 cap ({m0_used:.1f}MB used) — {risk}"
            )
            checks_passed += 1

        db_space_line = (
            f"📦 Data: <code>{data_mb:.1f}MB</code>  "
            f"💾 Storage: <code>{storage_mb:.1f}MB</code>  "
            f"🔖 Indexes: <code>{index_mb:.1f}MB</code>"
        )
        info_items.append(f"DB space — data:{data_mb:.1f}MB storage:{storage_mb:.1f}MB idx:{index_mb:.1f}MB")
    except Exception as space_err:
        db_space_line = ""
        db_bar_line   = ""
        info_items.append(f"DB space check skipped: {html.escape(str(space_err)[:50])}")

    # ═══════════════════════════════════════
    # GENERATE COMPREHENSIVE REPORT
    # ═══════════════════════════════════════
    
    scan_time = now_local().strftime('%Y-%m-%d %H:%M:%S')
    health_percentage = int((checks_passed / total_checks) * 100) if total_checks > 0 else 0
    
    # Determine overall status
    if health_percentage >= 90:
        status_icon = "✅"
        status_text = "EXCELLENT"
    elif health_percentage >= 70:
        status_icon = "⚠️"
        status_text = "GOOD"
    elif health_percentage >= 50:
        status_icon = "⚠️"
        status_text = "NEEDS ATTENTION"
    else:
        status_icon = "❌"
        status_text = "CRITICAL"
    
    report = f"🎛️ <b>BOT 2 DIAGNOSTIC REPORT</b>\n"
    report += "━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
    report += f"🕐 <b>Scan Time:</b> {scan_time}\n"
    report += f"💻 <b>Version:</b> Administrator v2.1\n"
    report += f"📊 <b>Health Score:</b> {checks_passed}/{total_checks} ({health_percentage}%)\n"
    report += f"🎯 <b>Status:</b> {status_icon} {status_text}\n"
    if db_space_line:
        report += f"🗄️ <b>Space:</b> {db_space_line}\n"
    if db_bar_line:
        report += f"📊 {db_bar_line}\n"
    report += "\n"
    
    # Critical issues section
    if issues:
        report += f"❌ <b>CRITICAL ALERTS ({len(issues)}):</b>\n"
        for i, issue in enumerate(issues, 1):
            report += f"{i}. {html.escape(str(issue))}\n"
        report += "\n"
    
    # Warnings section
    if warnings:
        report += f"⚠️ <b>WARNINGS ({len(warnings)}):</b>\n"
        for i, warning in enumerate(warnings, 1):
            report += f"{i}. {html.escape(str(warning))}\n"
        report += "\n"
    
    # System info
    if info_items:
        report += "ℹ️ <b>SYSTEM STATUS:</b>\n"
        for info in info_items[:5]:
            report += f"• {html.escape(str(info))}\n"
        report += "\n"
    
    # Final verdict
    if not issues and not warnings:
        report += "✅ <b>ALL SYSTEMS OPERATIONAL</b>\n"
        report += "Bot 2 admin panel is healthy and ready."
    elif issues:
        report += "🚨 <b>IMMEDIATE ACTION REQUIRED</b>\n"
        report += "Critical issues detected. Resolve to restore full admin functionality."
    else:
        report += "✅ <b>SYSTEM FUNCTIONAL</b>\n"
        report += "Minor warnings present. Monitor but system is operational."

    # ═══════════════════════════════════════
    # AUTO SOLUTIONS
    # ═══════════════════════════════════════
    solutions = []
    combined = issues + warnings

    for item in combined:
        item_l = item.lower()
        if "mongodb" in item_l or "database" in item_l or "db" in item_l:
            solutions.append(
                "<b>DB:</b> Check MONGO_URI in Render env vars. Ensure MongoDB Atlas IP Whitelist "
                "includes 0.0.0.0/0 (or your server IP). Verify Atlas cluster is not paused."
            )
        if "broadcast" in item_l or "broadcast collection" in item_l:
            solutions.append(
                "<b>Broadcast:</b> Use CANCEL BROADCAST from the broadcast menu to clear stuck entries."
            )
        if "backup" in item_l or "backups" in item_l:
            solutions.append(
                "Backups: Trigger manual backup via BACKUP MENU -> CREATE BACKUP. "
                "Check that the backups collection exists in MongoDB."
            )
        if "drive" in item_l or "token" in item_l:
            solutions.append(
                "Drive: Delete token.json and re-run Google Drive auth flow. "
                "Ensure DRIVE FOLDER ID env var is set in Render."
            )
        if "environment" in item_l or "env" in item_l or "missing" in item_l:
            solutions.append(
                "Env Vars: Open Render dashboard -> Environment -> add the missing variable, then redeploy."
            )
        if "latency" in item_l or "slow" in item_l or "timeout" in item_l:
            solutions.append(
                "Latency: Upgrade MongoDB Atlas tier (M0 to M10). Add indexes on frequently queried fields. "
                "Check Render region matches Atlas region for low ping."
            )
        if "msa" in item_l:
            solutions.append(
                "MSA IDs: Verify the msa ids collection is intact. "
                "Do NOT manually delete documents from it."
            )
        if "ban" in item_l or "banned" in item_l:
            solutions.append(
                "Bans: Review ban triggers in bot1 auto-ban logic. "
                "Use SHOOT -> SEARCH USER to inspect individual cases."
            )

    if not solutions and (issues or warnings):
        solutions.append(
            "General Fix: Restart Bot 2 service on Render. "
            "If issue persists, check Render logs for stack traces and contact developer."
        )

    if solutions:
        unique_solutions = list(dict.fromkeys(solutions))
        report += "\nPOSSIBLE SOLUTIONS:\n"
        for idx, sol in enumerate(unique_solutions, 1):
            report += f"{idx}. {sol}\n\n"

    # Safe truncation: cut at last newline to avoid splitting mid-sentence or mid-entity
    if len(report) > 3800:
        cut = report[:3750]
        last_nl = cut.rfind('\n')
        report = (cut[:last_nl] if last_nl > 0 else cut) + "\n\n(report truncated)"
    try:
        await status_msg.edit_text(report, parse_mode="HTML")
    except Exception as _diag_err:
        # Fallback: send plain text so the admin always gets something readable
        try:
            plain = f"BOT 2 DIAGNOSIS ERROR\n\nParse error: {str(_diag_err)[:200]}\n\nCheck Render logs."
            await status_msg.edit_text(plain)
        except Exception:
            pass

def _resolve_user(search_input: str):
    """
    Cross-collection multi-field user lookup for all SHOOT action handlers.
    Supports: MSA ID (exact or prefix), User ID, @username, and First Name starting letters.
    Checks col_user_tracking, col_msa_ids, and col_user_verification.
    Returns a merged dict or None if not found.
    """
    s = search_input.strip()
    if not s:
        return None

    import re
    clean_uname = s.lstrip("@").strip()

    tracking_doc = None
    msa_doc = None
    verif_doc = None

    # 1. MSA ID search (e.g. MSA001 or MSA)
    if s.upper().startswith("MSA"):
        msa_code = s.upper()
        msa_rx = re.compile(f"^{re.escape(msa_code)}", re.IGNORECASE)
        msa_doc = col_msa_ids.find_one({"msa_id": msa_rx})
        tracking_doc = col_user_tracking.find_one({"msa_id": msa_rx})

    # 2. Exact numeric User ID search
    elif s.isdigit():
        uid = int(s)
        tracking_doc = col_user_tracking.find_one({"user_id": uid})
        msa_doc = col_msa_ids.find_one({"user_id": uid})
        verif_doc = col_user_verification.find_one({"user_id": uid})

    # 3. Username / Name search
    if not tracking_doc and not msa_doc and clean_uname:
        prefix_rx = re.compile(f"^{re.escape(clean_uname)}", re.IGNORECASE)
        at_prefix_rx = re.compile(f"^@{re.escape(clean_uname)}", re.IGNORECASE)

        # Search username first
        tracking_doc = col_user_tracking.find_one({"$or": [{"username": prefix_rx}, {"username": at_prefix_rx}]})
        if not tracking_doc:
            msa_doc = col_msa_ids.find_one({"$or": [{"username": prefix_rx}, {"username": at_prefix_rx}]})

        # Search first_name if username not found
        if not tracking_doc and not msa_doc:
            tracking_doc = col_user_tracking.find_one({"first_name": prefix_rx})
        if not tracking_doc and not msa_doc:
            msa_doc = col_msa_ids.find_one({"first_name": prefix_rx})
        if not tracking_doc and not msa_doc:
            verif_doc = col_user_verification.find_one({"first_name": prefix_rx})

    if not tracking_doc and not msa_doc and not verif_doc:
        return None

    # Cross-link missing records by user_id
    target_uid = (tracking_doc or msa_doc or verif_doc).get("user_id")
    if target_uid:
        if not tracking_doc:
            tracking_doc = col_user_tracking.find_one({"user_id": target_uid})
        if not msa_doc:
            msa_doc = col_msa_ids.find_one({"user_id": target_uid})
        if not verif_doc:
            verif_doc = col_user_verification.find_one({"user_id": target_uid})

    return {
        "user_id":     target_uid,
        "msa_id":      (msa_doc or {}).get("msa_id") or (tracking_doc or {}).get("msa_id", "N/A"),
        "first_name":  (tracking_doc or {}).get("first_name") or (msa_doc or {}).get("first_name") or (verif_doc or {}).get("first_name", "Unknown"),
        "username":    (tracking_doc or {}).get("username") or (msa_doc or {}).get("username", "N/A"),
        "source":      (tracking_doc or {}).get("source", "N/A"),
        "first_start": (tracking_doc or {}).get("first_start"),
        "last_start":  (tracking_doc or {}).get("last_start"),
        "assigned_at": (msa_doc or {}).get("assigned_at"),
    }


