    await state.set_state(ShootStates.waiting_for_warning_text)
    
    back_kb = ReplyKeyboardMarkup(
        keyboard=[[KeyboardButton(text="⬅️ BACK"), KeyboardButton(text="❌ CANCEL")]],
        resize_keyboard=True
    )
