@dp.message(SupportStates.waiting_for_reply_id)
async def process_reply_id(message: types.Message, state: FSMContext):
    """Process user ID for reply"""
    if message.text in ["❌ CANCEL", "/cancel"]:
        await state.clear()
        await message.answer(
            "❌ Operation cancelled.",
            reply_markup=get_support_management_menu(),
            parse_mode="Markdown"
        )
        return
    
    search_id = message.text.strip().upper()
    
    user_id = None
    user_name = "User"
    msa_id = search_id if search_id.startswith("MSA") else "N/A"
    
    # Check if search term is digit (Telegram ID)
    is_telegram_id = search_id.isdigit()
    
    # 1. Try finding in support tickets first
    ticket = col_support_tickets.find_one({"msa_id": search_id}) if not is_telegram_id else col_support_tickets.find_one({"user_id": int(search_id)})
    
    if ticket:
        user_id = ticket.get('user_id')
        user_name = ticket.get('user_name', 'User')
        msa_id = ticket.get('msa_id', msa_id)
    else:
        # 2. If not found in tickets, search global MSA users collection
        if is_telegram_id:
            user_doc = col_msa_ids.find_one({"user_id": int(search_id)})
            if user_doc:
                user_id = user_doc.get("user_id")
                user_name = user_doc.get("first_name", "User")
                msa_id = user_doc.get("msa_id", "N/A")
        else:
            user_doc = col_msa_ids.find_one({"msa_id": search_id})
            if user_doc:
                user_id = user_doc.get("user_id")
                user_name = user_doc.get("first_name", "User")
                msa_id = user_doc.get("msa_id", search_id)
                
    if not user_id:
        await message.answer(
            f"❌ **User not found!**\n\n"
            f"No records found for ID: `{search_id}`\n\n"
            f"Try again or click ❌ CANCEL",
            parse_mode="Markdown"
        )
        return
    
    # Store user info and move to message composition
    await state.update_data(
        reply_user_id=user_id,
        reply_user_name=user_name,
        reply_msa_id=msa_id
    )
    await state.set_state(SupportStates.waiting_for_reply_message)
    
    quick_kb = ReplyKeyboardMarkup(
        keyboard=[
            [KeyboardButton(text="🚀 Issue Resolved & Access Restored")],
            [KeyboardButton(text="⏳ Investigating — We're on it!")],
            [KeyboardButton(text="🔒 Account Unlocked — Try again")],
            [KeyboardButton(text="❓ Need More Info / Screenshot")],
            [KeyboardButton(text="❌ CANCEL")]
        ],
        resize_keyboard=True
    )
    
    await message.answer(
        f"📨 **MESSAGING: {user_name}**\n\n"
        f"🆔 Telegram ID: `{user_id}`\n"
        f"💳 MSA+ ID: `{msa_id}`\n\n"
        f"⚡ **Select a Quick Reply Template below**, or type a custom message:",
        reply_markup=quick_kb,
        parse_mode="Markdown"
    )

@dp.message(SupportStates.waiting_for_reply_message)
async def process_reply_message(message: types.Message, state: FSMContext):
    """Send the reply message to user (supports Quick Templates & custom messages)"""
    txt = (message.text or message.caption or "").strip()
    if txt in ["❌ CANCEL", "/cancel"]:
        await state.clear()
        await message.answer(
            "❌ Operation cancelled.",
            reply_markup=get_support_management_menu(),
            parse_mode="Markdown"
        )
        return
    
    data = await state.get_data()
    user_id = data.get('reply_user_id')
    user_name = data.get('reply_user_name')

    # Quick template mapping
    templates = {
        "🚀 Issue Resolved & Access Restored": "✨ **Great news!** Your support request has been resolved by our admin team. Everything should be working smoothly now.",
        "⏳ Investigating — We're on it!": "⏳ Our technical support team is actively investigating your request. We will update you as soon as possible!",
        "🔒 Account Unlocked — Try again": "🔒 Your account restriction/lock has been lifted. Please try accessing bot features again.",
        "❓ Need More Info / Screenshot": "❓ Could you please provide additional details or a screenshot of the error you encountered so we can assist you better?"
    }

    auto_resolve = (txt == "🚀 Issue Resolved & Access Restored")
    reply_text = templates.get(txt, txt)
    
    if len(reply_text) < 5:
        await message.answer(
            "⚠️ **Message too short!**\n\nPlease send a meaningful message (min 5 characters).",
            parse_mode="Markdown"
        )
        return
    
    # Send message to user via Bot 1
    try:
        await bot_1.send_message(
            user_id,
            f"📨 **MESSAGE FROM ADMIN TEAM**\n"
            f"━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
            f"{reply_text}\n\n"
            f"━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
            f"💡 Need more help? Use **📞 SUPPORT** in the menu.\n\n"
            f"💎 **MSA NODE Team**",
            parse_mode="Markdown"
        )

        resolved_note = ""
        if auto_resolve:
            res_result = col_support_tickets.update_many(
                {"user_id": user_id, "status": "open"},
                {"$set": {"status": "resolved", "resolved_at": now_local()}}
            )
            if res_result.modified_count > 0:
                resolved_note = f"\n✅ `{res_result.modified_count}` open ticket(s) automatically marked as **RESOLVED**!"
        
        await state.clear()
        await message.answer(
            f"✅ **Message sent to {user_name}!**\n\n"
            f"🆔 User ID: `{user_id}`\n"
            f"📨 Your message was delivered successfully.{resolved_note}",
            reply_markup=get_support_management_menu(),
            parse_mode="Markdown"
        )
        print(f"📨 Admin sent reply to user {user_id} (auto_resolve={auto_resolve})")
        
    except Exception as e:
        await state.clear()
        await message.answer(
            f"❌ **Failed to send message!**\n\n"
            f"Error: {str(e)}\n\n"
            f"User may have blocked the bot.",
            reply_markup=get_support_management_menu(),
            parse_mode="Markdown"
        )
        print(f"❌ Failed to send reply to user {user_id}: {str(e)}")

