    if not await has_permission(message.from_user.id, "backup"):
        await state.clear(); return
    txt = (message.text or "").strip().upper()
    if "MAIN MENU" in txt:
        await state.clear(); return await back_to_main(message, state)
    if "BACK" in txt:
        await state.clear()
